import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  // ---------------- Unified error handler ----------------
  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      alert(err.response?.data?.error || err.message);
    }
  };

  // ---------------- Backend API calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      setResults(res.data.positionResults);
      setWinners(res.data.winners);
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Initial load ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }

    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchResults();
    };
    init();
  }, [token]);

  // ---------------- JSX ----------------
  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b shadow-sm py-4 px-8 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-800">iVote Admin Dashboard</h1>
        <button
          onClick={() => {
            logout();
            navigate("/login");
          }}
          className="bg-red-600 text-white px-5 py-2 rounded-lg hover:bg-red-700 transition"
        >
          Logout
        </button>
      </header>

      <main className="p-8 grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-7xl mx-auto">
        {/* Voting Status */}
        <section className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition p-6 border border-gray-100">
          <div className="flex justify-between items-center">
            <div>
              <h2 className="text-lg font-bold text-gray-800">Voting Status</h2>
              <p
                className={`mt-1 text-sm font-medium ${
                  votingOpen ? "text-green-600" : "text-red-600"
                }`}
              >
                {votingOpen ? "Open" : "Closed"}
              </p>
            </div>
            <button
              onClick={toggleVoting}
              className={`px-5 py-2 rounded-xl font-semibold text-white shadow-sm transition 
                ${
                  votingOpen
                    ? "bg-red-600 hover:bg-red-700"
                    : "bg-green-600 hover:bg-green-700"
                }`}
            >
              {votingOpen ? "Close Voting" : "Open Voting"}
            </button>
          </div>
        </section>

        {/* Pending Users */}
        <section className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition p-6 border border-gray-100">
          <h2 className="text-lg font-bold text-gray-800 mb-4">
            Pending Voter Registrations
          </h2>
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500 italic">No pending users.</p>
          ) : (
            <div className="overflow-hidden rounded-lg border border-gray-200">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 text-gray-700">
                  <tr>
                    <th className="px-4 py-2 text-left">Student Number</th>
                    <th className="px-4 py-2 text-left">Name</th>
                    <th className="px-4 py-2 text-left">Email</th>
                    <th className="px-4 py-2 text-center">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {pendingUsers.map((user) => (
                    <tr key={user.id} className="hover:bg-gray-50">
                      <td className="px-4 py-2">{user.studentNumber}</td>
                      <td className="px-4 py-2">{user.name}</td>
                      <td className="px-4 py-2">{user.email}</td>
                      <td className="px-4 py-2 text-center space-x-2">
                        <button
                          onClick={() => approveUser(user.id)}
                          className="bg-green-600 text-white px-3 py-1 rounded-lg hover:bg-green-700 shadow-sm"
                        >
                          Approve
                        </button>
                        <button
                          onClick={() => rejectUser(user.id)}
                          className="bg-red-600 text-white px-3 py-1 rounded-lg hover:bg-red-700 shadow-sm"
                        >
                          Reject
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {/* Candidates */}
        <section className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition p-6 border border-gray-100 lg:col-span-2">
          <h2 className="text-lg font-bold text-gray-800 mb-4">Candidates</h2>
          <div className="overflow-hidden rounded-lg border border-gray-200">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 text-gray-700">
                <tr>
                  <th className="px-4 py-2 text-left">Name</th>
                  <th className="px-4 py-2 text-left">Position</th>
                  <th className="px-4 py-2 text-left">Party</th>
                  <th className="px-4 py-2 text-center">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {candidates.map((c) => (
                  <tr key={c.id} className="hover:bg-gray-50">
                    <td className="px-4 py-2">{c.name}</td>
                    <td className="px-4 py-2">{c.position}</td>
                    <td className="px-4 py-2">{c.party || "-"}</td>
                    <td className="px-4 py-2 text-center">
                      <button
                        onClick={() => deleteCandidate(c.id)}
                        className="bg-red-600 text-white px-3 py-1 rounded-lg hover:bg-red-700 shadow-sm"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        {/* System Logs */}
        <section className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition p-6 border border-gray-100">
          <h2 className="text-lg font-bold text-gray-800 mb-4">System Logs</h2>
          {logs.length === 0 ? (
            <p className="text-gray-500 italic">No logs available.</p>
          ) : (
            <ul className="space-y-2 max-h-64 overflow-y-auto text-sm">
              {logs.map((log) => (
                <li
                  key={log.id}
                  className="flex justify-between border-b pb-1 text-gray-700"
                >
                  <span>{log.action}</span>
                  <span className="text-gray-400">
                    {new Date(log.createdAt).toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Election Results */}
        <section className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition p-6 border border-gray-100 lg:col-span-2">
          <h2 className="text-lg font-bold text-gray-800 mb-4">
            Election Results
          </h2>
          {Object.keys(results).length === 0 ? (
            <p className="text-gray-500 italic">No results available yet.</p>
          ) : (
            Object.keys(results).map((pos) => (
              <div key={pos} className="mb-6">
                <h3 className="text-md font-semibold text-gray-700 mb-2">{pos}</h3>
                <div className="overflow-hidden rounded-lg border border-gray-200">
                  <table className="w-full text-sm">
                    <thead className="bg-gray-50 text-gray-700">
                      <tr>
                        <th className="px-4 py-2 text-left">Name</th>
                        <th className="px-4 py-2 text-left">Party</th>
                        <th className="px-4 py-2 text-center">Votes</th>
                        <th className="px-4 py-2 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                      {results[pos].map((c) => (
                        <tr key={c.id} className="hover:bg-gray-50">
                          <td className="px-4 py-2">{c.name}</td>
                          <td className="px-4 py-2">{c.party || "-"}</td>
                          <td className="px-4 py-2 text-center">{c.votes}</td>
                          <td className="px-4 py-2 text-center font-medium">
                            {winners[pos]?.id === c.id ? (
                              <span className="text-green-600">Winner</span>
                            ) : (
                              <span className="text-gray-400">—</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))
          )}
        </section>

        {/* Reports */}
        <section className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition p-6 border border-gray-100">
          <h2 className="text-lg font-bold text-gray-800 mb-4">Reports</h2>
          <button
            onClick={generateReport}
            className="bg-blue-600 text-white px-5 py-2 rounded-lg hover:bg-blue-700 transition shadow-sm"
          >
            Generate Final Report
          </button>
          {reportHash && (
            <p className="mt-3 text-gray-600 text-sm">
              Cryptographic Hash:{" "}
              <span className="font-mono">{reportHash}</span>
            </p>
          )}
        </section>
      </main>
    </div>
  );
}
